CREATE DATABASE IF NOT EXISTS nowline;
USE nowline;
CREATE TABLE IF NOT EXISTS users(id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS votes(user_id BIGINT PRIMARY KEY, choice ENUM('yes','no') NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS subscribers(email VARCHAR(254) PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS donations(id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL CHECK(amount>0), frequency ENUM('monthly','onetime') NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS donation_total(id INT PRIMARY KEY, total DECIMAL(14,2) NOT NULL DEFAULT 0);
INSERT IGNORE INTO donation_total VALUES(1,0);
CREATE OR REPLACE VIEW donation_summary AS SELECT frequency, COUNT(*) AS contributions, SUM(amount) AS total FROM donations GROUP BY frequency;
